@dataclass
class View:
    """ A view allows us to pre-define a query to run on a dataset
    """

    # The source query to run
    query: "Query"

    @classmethod
    def from_fbs(cls, o: FbsView) -> Self:
        query_obj = o.Query()
        if query_obj is not None:
            query = Query.from_fbs(query_obj)
        else:
            raise ValueError("Query is required")
        return cls(query)

    @classmethod
    def from_bytes(cls, data: bytes) -> Self:
        deprefixed = RemoveSizePrefix(data, 0)
        o = FbsView.GetRootAs(deprefixed[0], deprefixed[1])
        return cls.from_fbs(o)

    def serialize_to(self, builder: Builder) -> int:
        from .generated.View import (
            Start,
            AddQuery,
            End,
        )
        query_offset = self.query.serialize_to(builder)

        Start(builder)
        AddQuery(builder, query_offset)
        return End(builder)

    def to_bytes(self) -> bytes:
        builder = Builder(0)
        offset = self.serialize_to(builder)
        builder.FinishSizePrefixed(offset)
        return builder.Output()

    @classmethod
    def make_default(cls) -> Self:
        query = Query.make_default()
        return cls(query)

    def __eq__(self, other) -> bool:
        eq = True
        eq = eq and self.query == other.query

        return eq
